// Separator — Gtk.Separator
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles separator with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface SeparatorProps extends WidgetProps {
  className?: string
  children?: ReactNode

}

export function Separator({ className, children }: SeparatorProps) {
  return (
    <div className={cn("bg-[color-mix(in_srgb,currentColor_var(--border-opacity),transparent)]", "min-w-[1px]", "min-h-[1px]", className)}>
      {children}
    </div>
  )
}
